from cardio_1 import a, G
# J47 — Bronchectasies (P-02-Pneumologie). Clés absentes du glossaire au 09.10.2026 ; aucune collision vérifiée dans les autres cours.
a('BSI', [('B', 'Bronchiectasis (bronchectasies)'), ('S', 'Severity (gravité)'), ('I', 'Index (indice)')], 'Indice de gravité des bronchectasies', '<p>Score pronostique de Chalmers et collaborateurs (2014) qui additionne neuf variables : âge, indice de masse corporelle, VEMS, hospitalisation antérieure, exacerbations, dyspnée, colonisation par <i>Pseudomonas aeruginosa</i> ou par un autre germe, étendue radiologique. Forme légère de 0 à 4 points, modérée de 5 à 8, sévère à partir de 9.</p>', 'j47-bsi')
a('FACED', [('F', 'FEV1 (VEMS)'), ('A', 'Age (âge)'), ('C', 'Chronic colonisation (colonisation chronique par Pseudomonas aeruginosa)'), ('E', 'Extension (étendue radiologique)'), ('D', 'Dyspnoea (dyspnée)')], 'Score FACED', '<p>Score pronostique de Martínez-García et collaborateurs (2014), construit pour prédire la mortalité à cinq ans : total de 0 à 7 points, forme légère de 0 à 2, modérée de 3 à 4, sévère de 5 à 7.</p>', 'j47-faced')
a('EMBARC', [('E', 'European (européen)'), ('M', 'Multicentre (multicentrique)'), ('B', 'Bronchiectasis (bronchectasies)'), ('A', 'Audit and (audit et)'), ('R', 'Research (recherche)'), ('C', 'Collaboration')], 'Réseau européen multicentrique de recherche sur les bronchectasies', '<p>Réseau de recherche clinique dont le registre prospectif a inclus 16 963 adultes dans 27 pays européens et en Israël entre 2015 et 2022.</p>', 'j47-embarc')
a('DPP1', [('D', 'Dipeptidyl'), ('P', 'Peptidase'), ('P', ''), ('1', 'type 1')], 'Dipeptidyl peptidase 1', '<p>Enzyme qui active, pendant la maturation médullaire du neutrophile, l’élastase neutrophile, la cathepsine G et la protéinase 3. Le brensocatib l’inhibe de façon compétitive et réversible.</p>', 'j47-brensocatib')
a('ASPEN', [('ASPEN', 'nom propre de l’essai de phase 3 du brensocatib, non développable lettre à lettre')], 'Essai ASPEN (brensocatib, 2025)', '<p>Essai randomisé de 52 semaines chez 1721 patients (1680 adultes et 41 adolescents) : taux annuels d’exacerbation de 1,02 (10 mg), 1,04 (25 mg) et 1,29 (placebo), soit des rapports de taux de 0,79 et 0,81 (Chalmers, 2025).</p>', 'j47-brensocatib')
a('EMBRACE', [('EMBRACE', 'nom propre de l’essai néo-zélandais de l’azithromycine, non développable lettre à lettre')], 'Essai EMBRACE (azithromycine, 2012)', '<p>Essai randomisé néo-zélandais de 141 patients : l’azithromycine à 500 mg trois fois par semaine pendant six mois a réduit le taux d’exacerbations de 1,57 à 0,59 par patient (rapport de taux 0,38 ; Wong, 2012).</p>', 'j47-macrolides')
a('BAT', [('B', 'Bronchiectasis (bronchectasies)'), ('A', 'and Long-term Azithromycin (et azithromycine au long cours)'), ('T', 'Treatment (traitement)')], 'Essai BAT (azithromycine, 2013)', '<p>Essai randomisé néerlandais de 83 patients ayant eu au moins trois infections respiratoires basses dans l’année : l’azithromycine à 250 mg par jour pendant un an a abaissé la médiane des exacerbations de 2 à 0 (Altenburg, 2013).</p>', 'j47-macrolides')
a('BLESS', [('BLESS', 'nom propre de l’essai australien de l’érythromycine à faible dose, non développable lettre à lettre')], 'Essai BLESS (érythromycine, 2013)', '<p>Essai randomisé australien de 117 patients : l’éthylsuccinate d’érythromycine à 400 mg deux fois par jour pendant douze mois a réduit les exacerbations (rapport de taux 0,57) mais augmenté la résistance aux macrolides des streptocoques oropharyngés (Serisier, 2013).</p>', 'j47-macrolides')
a('PROMIS', [('PROMIS', 'nom propre du programme de phase 3 du colistiméthate inhalé (PROMIS-I et PROMIS-II), non développable lettre à lettre')], 'Essais PROMIS (colistiméthate inhalé, 2024)', '<p>Deux essais randomisés de douze mois chez des patients infectés par <i>Pseudomonas aeruginosa</i> : PROMIS-I a montré une baisse du taux annuel d’exacerbations (0,58 contre 0,95) ; PROMIS-II, interrompu par la pandémie de COVID-19, ne l’a pas reproduite (Haworth, 2024).</p>', 'j47-inhales')
for k, n in [('PROMIS-I', 'premier'), ('PROMIS-II', 'second')]:
    a(k, [(k, 'nom propre du ' + n + ' essai du programme PROMIS, non développable lettre à lettre')], 'Essai ' + k + ' (colistiméthate inhalé, 2024)', '<p>Voir le programme PROMIS : essai randomisé contre placebo du colistiméthate nébulisé chez des patients atteints de bronchectasies et infectés par <i>Pseudomonas aeruginosa</i> (Haworth, 2024).</p>', 'j47-inhales')
a('mucA', [('muc', 'mucoïdie'), ('A', 'gène A')], 'Gène mucA de Pseudomonas aeruginosa', '<p>Gène d’un facteur anti-sigma qui freine la synthèse d’alginate. Ses mutations rendent la souche mucoïde et favorisent l’infection chronique.</p>', 'j47-biofilm')
a('PCV20', [('P', 'Pneumococcal (pneumococcique)'), ('C', 'Conjugate (conjugué)'), ('V', 'Vaccine (vaccin)'), ('20', '20 sérotypes')], 'Vaccin pneumococcique conjugué 20-valent', '<p>Vaccin conjugué couvrant 20 sérotypes de pneumocoque ; option recommandée par le Plan de vaccination suisse 2026 pour les adultes à risque et dès 65 ans.</p>', 'j47-vaccination')
a('PCV21', [('P', 'Pneumococcal (pneumococcique)'), ('C', 'Conjugate (conjugué)'), ('V', 'Vaccine (vaccin)'), ('21', '21 sérotypes')], 'Vaccin pneumococcique conjugué 21-valent', '<p>Vaccin conjugué couvrant 21 sérotypes de pneumocoque ; premier vaccin autorisé en Suisse pour les 18 à 64 ans selon le Plan de vaccination suisse 2026.</p>', 'j47-vaccination')
a('BMJ', [('B', 'British (britannique)'), ('M', 'Medical (médical)'), ('J', 'Journal (revue)')], 'British Medical Journal', '<p>Éditeur de revues médicales ; le résumé de la recommandation de la British Thoracic Society sur les bronchectasies a paru dans BMJ Open Respiratory Research en 2018.</p>')
a('ERJ', [('E', 'European (européenne)'), ('R', 'Respiratory (de pneumologie)'), ('J', 'Journal (revue)')], 'European Respiratory Journal', '<p>Revue de la Société européenne de pneumologie ; ERJ Open Research en est la revue en libre accès.</p>')
a('Bustamante-Marin', [('Bustamante-Marin', 'Ximena M. Bustamante-Marin, biologiste, première autrice')], 'Bustamante-Marin et Ostrowski, Cold Spring Harbor Perspectives in Biology 2017', '<p>Revue de la clairance mucociliaire : couche de mucus, liquide de surface des voies aériennes et cils battant en ondes métachrones.</p>', 'j47-clairance')
a('Martínez-García', [('Martínez-García', 'Miguel Ángel Martínez-García, pneumologue espagnol, premier auteur')], 'Martínez-García et collaborateurs, European Respiratory Journal 2014', '<p>Publication du score FACED, construit sur 819 patients pour prédire la mortalité à cinq ans des bronchectasies non liées à la mucoviscidose.</p>', 'j47-faced')
